import math

def run(f, fp, x, n):
    for i in range(n):
        x = x - f(x) / fp(x)
        print(f"x{i + 1} = {x:.10f}")

k = int(input())
for i in range(k):
    words = input().split()
    n = int(words[len(words) - 1])
    if words[0] == "cos":
        run(lambda x: math.cos(x) - x, lambda x: -math.sin(x) - 1, float(words[1]), n)
    else:
        c3, c2, c1, c0, x0 = [float(w) for w in words[1:6]]
        f = lambda x: c3*x**3 + c2*x**2 + c1*x + c0
        fp = lambda x: 3*c3*x**2 + 2*c2*x + c1
        run(f, fp, x0, n)

