def newton(f, fp, x, tol, max_steps):
    steps = 0
    while steps < max_steps:
        slope = fp(x)
        if slope == 0:
            return x, steps, "flat tangent"
        new = x - f(x) / slope
        steps = steps + 1
        if abs(new - x) < tol:
            return new, steps, "converged"
        x = new
    return x, steps, "no convergence"

def cbrt(t):
    if t < 0:
        return -(-t) ** (1/3)
    return t ** (1/3)

def report(label, f, fp, x0):
    root, steps, status = newton(f, fp, x0, 1e-10, 50)
    print(f"{label}, from {x0}")
    if status == "converged":
        print(f"  converged to {root:.10f} in {steps} steps, check f = {f(root):.1e}")
    elif status == "flat tangent":
        print(f"  stopped after {steps} steps: f'({root}) = 0, a flat tangent")
    else:
        print(f"  no convergence in {steps} steps: last guess {root:.3e}, f there {f(root):.3e}")

f = lambda x: x**3 - 2*x + 2
fp = lambda x: 3*x**2 - 2
report("The plain case: x^2 - 2", lambda x: x**2 - 2, lambda x: 2*x, 1.0)
report("Example 1 · a flat tangent: x^2 - 2", lambda x: x**2 - 2, lambda x: 2*x, 0.0)
report("Example 2 · a cycle: x^3 - 2x + 2", f, fp, 0.0)
report("Example 3 · running off: the cube root of x", cbrt, lambda x: 1 / (3 * cbrt(x)**2), 1.0)
report("Example 4 · the wrong root: x^3 - x", lambda x: x**3 - x, lambda x: 3*x**2 - 1, 0.5)
report("Example 6 · start close: x^3 - 2x + 2", f, fp, -1.5)
report("Example 7 · no real root: x^2 + 1", lambda x: x**2 + 1, lambda x: 2*x, 1.0)

