def newton(f, fp, x, tol, max_steps):
    steps = 0
    while steps < max_steps:
        slope = fp(x)
        if slope == 0:
            return x, steps, "flat tangent"
        new = x - f(x) / slope
        steps = steps + 1
        if abs(new - x) < tol:
            return new, steps, "converged"
        x = new
    return x, steps, "no convergence"

k = int(input())
for i in range(k):
    words = input().split()
    c3, c2, c1, c0 = [float(w) for w in words[:4]]
    x0 = float(words[4])
    f = lambda x: c3*x**3 + c2*x**2 + c1*x + c0
    fp = lambda x: 3*c3*x**2 + 2*c2*x + c1
    root, steps, status = newton(f, fp, x0, 1e-10, 50)
    if status == "converged":
        print(f"converged to {root:.10f} in {steps} steps")
    elif status == "flat tangent":
        print(f"flat tangent at {root:.10f} after {steps} steps")
    else:
        print(f"no convergence after {steps} steps")
